+const LOG_FORMAT = "%H%x1f%h%x1f%s%x1f%cr%x1e";
+
+export function parseLog(
+	output: string,
+	unpushed: Set<string>,
+	hasUpstream: boolean,
+) {
+	const commits: SourceControlCommit[] = [];
+	for (const record of output.split("\x1e")) {
+		const trimmed = record.replace(/^\n/, "");
+		if (!trimmed) continue;
+		const [sha, shortSha, subject, relativeDate] = trimmed.split("\x1f");
+		if (!sha || !shortSha) continue;
+		commits.push({
+			sha,
+			shortSha,
+			subject: subject ?? "",
+			relativeDate: relativeDate ?? "",
+			pushed: hasUpstream ? !unpushed.has(sha) : true,
+		});
+	}
+	return commits;
+}
+
+export function countLines(text: string): number {
+	if (!text) return 0;
+	let count = 0;
+	for (let index = 0; index < text.length; index++) {
+		if (text.charCodeAt(index) === 10) count++;
+	}
+	return text.endsWith("\n") ? count : count + 1;
+}
