+/**
+ * Old/new contents for a root-relative path. `staged` compares HEAD to the
+ * index; otherwise the index (or HEAD for untracked paths, which have no
+ * index entry) to the working tree.
+ */
+export async function getGitFileDiff(
+	git: GitRunner,
+	readWorkingFile: (path: string) => Promise<string | null>,
+	environmentId: string,
+	path: string,
+	staged: boolean,
+): Promise<GitFileDiff> {
+	const show = (rev: string) =>
+		git(["show", `${rev}:${path}`]).then(
+			(text) => text,
+			() => undefined,
+		);
+	if (staged) {
+		const [oldText, newText] = await Promise.all([show("HEAD"), show("")]);
+		return {
+			environmentId,
+			path,
+			oldText,
+			newText: newText ?? "",
+			binary: (oldText ?? newText ?? "").includes("\0"),
+		};
+	}
+	const [oldText, working] = await Promise.all([
+		show(""),
+		readWorkingFile(path),
+	]);
+	return {
+		environmentId,
+		path,
+		oldText,
+		newText: working ?? "",
+		binary: working === null || (oldText ?? "").includes("\0"),
+	};
+}
